plugins {
    alias(libs.plugins.kotlinMultiplatform)
    alias(libs.plugins.ksp)
}

// Compile-only check of the code generated by `ksp-plugin` for `@AutoGenerateField`:
// the build passes when the generated factories type-check against `field`.
// No Android target on purpose: KSP's AGP floor (8.12) is newer than the AGP this repo pins,
// and the generated code is pure common Kotlin anyway.
kotlin {
    jvmToolchain(17)
    jvm()
    wasmJs { browser() }

    sourceSets {
        commonMain.dependencies {
            implementation("me.tbsten.compose.preview.lab:annotation:${libs.versions.composePreviewLab.get()}")
            implementation("me.tbsten.compose.preview.lab:field:${libs.versions.composePreviewLab.get()}")
        }
        commonTest.dependencies {
            implementation(kotlin("test"))
        }
    }
}

dependencies {
    // Opt-in KSP processor backing @AutoGenerateField. Resolved via the composite build
    // (`includeBuild("../")`); external projects use the published coordinate.
    add("kspCommonMainMetadata", "me.tbsten.compose.preview.lab:ksp-plugin:${libs.versions.composePreviewLab.get()}")
}

// KSP Multiplatform Workaround
// Enables KSP-generated code in commonMain for multiplatform projects
fun Project.setupKspForMultiplatformWorkaround() {
    kotlin.sourceSets.commonMain {
        kotlin.srcDir("build/generated/ksp/metadata/commonMain/kotlin")
    }
    tasks.configureEach {
        if (name.startsWith("ksp") && name != "kspCommonMainKotlinMetadata") {
            dependsOn(tasks.named("kspCommonMainKotlinMetadata"))
            enabled = false
        }
    }
}
setupKspForMultiplatformWorkaround()
